  "metadata": {
    "title": "Basler Rheinschiffahrt-Aktiengesellschaft",
    "date": "1928-03-22",
    "sender": "Basler Rheinschiffahrt-Aktiengesellschaft",
    "receiver": "Herrn Dr. Vischer, Präsident, Herrn Christ, Vizepräsident und Herrn Ottinger",
    "location": "Basel"
  },
  "content": {
    "introduction": "In der heutigen Sitzung des Verwaltungsrates wurde beschlossen, den Mitgliedern des Verwaltungsrates und den Aktionären unserer Gesellschaft die nachstehenden Mitteilungen zu machen.",
    "main_content": [
      {
        "topic": "Jahresrechnung",
        "details": "Die Jahresrechnung für das Jahr 1927 wurde vorgelegt und genehmigt. Es wurde beschlossen, den Gewinnanteil den Aktionären in Form von Aktien zu gewähren."
      },
      {
        "topic": "Erhöhung des Aktienkapitals",
        "details": "Der Verwaltungsrat hat beschlossen, das Aktienkapital unserer Gesellschaft um Fr. 1.500.000 zu erhöhen. Die neuen Aktien werden den bisherigen Aktionären angeboten."
      },
      {
        "topic": "Wahl des Präsidenten",
        "details": "Herr Dr. Vischer wurde einstimmig als Präsident des Verwaltungsrates wiedergewählt."
      }
    ],
    "conclusion": "Wir bitten die Herren Aktionäre, sich für die bevorstehende Generalversammlung zu melden, um ihre Stimme abzugeben."
  },
  "signature": "hochachtend, BASLER RHEINSCHIFFFAHRT-AKTIENGESELLSCHAFT"
}

